def write(p,rows,fields):
 with p.open('w') as f:
  w=csv.DictWriter(f,fields,delimiter='\t');w.writeheader();w.writerows(rows)
fs=[dict(zip(['id','severity','class','selector','claim','exact evidence','required correction'],r)) for r in FINDINGS]
# Requested columns remain exact; IDs are placed in evidence/claim prose rather than an extra column.
write(O/'findings.tsv',[{k:v for k,v in r.items() if k!='id'} for r in fs],['severity','class','selector','claim','exact evidence','required correction'])
assigned=json.loads(Path('/home/exedev/work/inputs/context/class-assignments.json').read_text())['groups']['spec-3']['classes'];assert set(NOTES)==set(assigned) and len(NOTES)==37
correct={r['class'] for r in fs};reviews=[];sample=[]
methodrows=list(csv.DictReader((W/'methods.tsv').open(),delimiter='\t'))
for cl in assigned:
 vas,ev,limits=NOTES[cl];addresses={int(a,16) for a in vas.split()}
 for r in methodrows:
  if r['class_name']==cl and int(r['imp_va'],16) in addresses:
   sample.append(dict(class_name=cl,category=r['category'],kind=r['kind'],selector=r['selector'],imp_va=r['imp_va'],review_scope='focused manual body review; no runtime/ABI guarantee'))
 reviews.append(dict(class_name=cl,result='CORRECTION_REQUIRED' if cl in correct else 'PASS_WITH_LIMITS',evidence=f"Inventory/layout/matrix verified; selected body VAs {', '.join(hex(a) for a in sorted(addresses))}. {ev}",limits=limits))
write(O/'class-review.tsv',reviews,['class_name','result','evidence','limits'])
write(O/'evidence/manual-body-sample.tsv',sample,['class_name','category','kind','selector','imp_va','review_scope'])
(O/'evidence/review-summary.json').write_text(json.dumps(dict(classes_reviewed=len(reviews),class_results=dict(collections.Counter(r['result'] for r in reviews)),findings_by_severity=dict(collections.Counter(r['severity'] for r in fs)),manual_method_rows=len(sample),manual_distinct_imps=len({r['imp_va'] for r in sample}),manual_review_is_not_exhaustive=True),indent=2)+'\n')
print((O/'evidence/review-summary.json').read_text())
